G=load()
I=G['Demo pair 1 input']; O=G['Demo pair 1 output']

def solve(g):
    H,W=len(g),len(g[0])
    vals=[v for row in g for v in row]
    bg=max(set(vals),key=lambda x:vals.count(x))
    # anchor: solid 2x2 (or larger) rectangle of a single non-bg color
    best=None
    for col in {v for row in g for v in row if v!=bg}:
        pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]==col]
        if len(pts)==4 and max(r for r,_ in pts)-min(r for r,_ in pts)==1 and max(c for _,c in pts)-min(c for _,c in pts)==1:
            best=col; break
    out=[row[:] for row in g]
    if best is None: return out
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]==best]
    cr=(min(r for r,_ in pts)+max(r for r,_ in pts))/2
    cc=(min(c for _,c in pts)+max(c for _,c in pts))/2
    changed=True
    while changed:
        changed=False
        for r in range(H):
            for c in range(W):
                v=g[r][c]
                if v!=bg and v!=best:
                    for rr,cc_ in [(int(2*cr-r),c),(r,int(2*cc-c)),(int(2*cr-r),int(2*cc-c))]:
                        if 0<=rr<H and 0<=cc_<W and out[rr][cc_]==bg:
                            out[rr][cc_]=v; changed=True
    return out

print('demo match:', solve(I)==O)
